import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { FEATURE_FLAGS } from 'lib/constants'
import { featureFlagLogic, FeatureFlagsSet } from 'lib/logic/featureFlagLogic'

import { eventsRetentionDeletionWarningLogic } from '~/layout/eventsRetentionDeletionWarningLogic'

import { healthSummaryLogic } from './healthSummaryLogic'

export type HelpBadgeStatus = 'danger' | 'warning' | 'success'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface helpMenuLogicValues {
    alertVisible: boolean // eventsRetentionDeletionWarningLogic
    featureFlags: FeatureFlagsSet // featureFlagLogic
    criticalCount: number // healthSummaryLogic
    unsnoozedCount: number // healthSummaryLogic
    warningCount: number // healthSummaryLogic
    hasHealthIssue: boolean
    healthBadgeContent: string
    healthBadgeStatus: HelpBadgeStatus
    isHelpMenuOpen: boolean
    isOldNavigation: boolean
    triggerBadgeContent: string
    triggerBadgeStatus: HelpBadgeStatus
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface helpMenuLogicActions {
    snooze: () => {
        value: true
    } // eventsRetentionDeletionWarningLogic
    setHelpMenuOpen: (isOpen: boolean) => {
        isOpen: boolean
    }
    toggleHelpMenu: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface helpMenuLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        hasHealthIssue: (unsnoozedCount: number) => boolean
        healthBadgeContent: (hasHealthIssue: boolean) => string
        healthBadgeStatus: (hasHealthIssue: boolean, criticalCount: number, warningCount: number) => HelpBadgeStatus
        triggerBadgeContent: (hasHealthIssue: boolean, alertVisible: boolean) => string
        triggerBadgeStatus: (
            hasHealthIssue: boolean,
            healthBadgeStatus: HelpBadgeStatus,
            alertVisible: boolean
        ) => HelpBadgeStatus
        isOldNavigation: (featureFlags: FeatureFlagsSet) => boolean
    }
}

export type helpMenuLogicType = MakeLogicType<
    helpMenuLogicValues,
    helpMenuLogicActions,
    Record<string, any>,
    helpMenuLogicMeta
>

export const helpMenuLogic = kea<helpMenuLogicType>([
    path(['lib', 'components', 'HelpMenu', 'helpMenuLogic']),
    connect(() => ({
        values: [
            healthSummaryLogic,
            ['unsnoozedCount', 'criticalCount', 'warningCount'],
            eventsRetentionDeletionWarningLogic,
            ['alertVisible'],
            featureFlagLogic,
            ['featureFlags'],
        ],
        actions: [eventsRetentionDeletionWarningLogic, ['snooze']],
    })),
    actions({
        setHelpMenuOpen: (isOpen: boolean) => ({ isOpen }),
        toggleHelpMenu: true,
    }),
    reducers({
        isHelpMenuOpen: [
            false,
            {
                setHelpMenuOpen: (_, { isOpen }) => isOpen,
                toggleHelpMenu: (state) => !state,
            },
        ],
    }),
    selectors({
        hasHealthIssue: [(s) => [s.unsnoozedCount], (unsnoozedCount: number): boolean => unsnoozedCount > 0],
        healthBadgeContent: [
            (s) => [s.hasHealthIssue],
            (hasHealthIssue: boolean): string => (hasHealthIssue ? '!' : ''),
        ],
        healthBadgeStatus: [
            (s) => [s.hasHealthIssue, s.criticalCount, s.warningCount],
            (hasHealthIssue: boolean, criticalCount: number, warningCount: number): HelpBadgeStatus => {
                if (!hasHealthIssue) {
                    return 'success'
                }
                if (criticalCount > 0) {
                    return 'danger'
                }
                if (warningCount > 0) {
                    return 'warning'
                }
                return 'success'
            },
        ],
        triggerBadgeContent: [
            (s) => [s.hasHealthIssue, s.alertVisible],
            (hasHealthIssue: boolean, alertVisible: boolean): string => (hasHealthIssue || alertVisible ? '!' : ''),
        ],
        triggerBadgeStatus: [
            (s) => [s.hasHealthIssue, s.healthBadgeStatus, s.alertVisible],
            (hasHealthIssue: boolean, healthBadgeStatus: HelpBadgeStatus, alertVisible: boolean): HelpBadgeStatus => {
                if (hasHealthIssue) {
                    return healthBadgeStatus
                }
                return alertVisible ? 'warning' : 'success'
            },
        ],
        isOldNavigation: [
            (s) => [s.featureFlags],
            (featureFlags: FeatureFlagsSet): boolean => !featureFlags[FEATURE_FLAGS.TODAY_RAIL_NAV],
        ],
    }),
    listeners(({ actions, values }) => {
        const snoozeRetentionWarningOnOpen = (): void => {
            if (values.isHelpMenuOpen && values.isOldNavigation && values.alertVisible) {
                actions.snooze()
            }
        }
        return {
            setHelpMenuOpen: snoozeRetentionWarningOnOpen,
            toggleHelpMenu: snoozeRetentionWarningOnOpen,
        }
    }),
])
